/* The AI website builder as a coding agent (round L, docs/ai-builder/architecture.md). Run after 380. ai_site_jobs gains what a multi minute agent job needs: which engine runs it (classic, the five step pipeline, or agent, the tool loop), how it started (blank or inside a theme, the chip and preferences in options), its budget, the phase and iteration it is on, its saved checkpoint (bounded), a cancel request, the last event number; a job may now be cancelled and be on the agent step; one queued or running job per website (skipped with a notice while two already exist). New table ai_site_job_events: what the job did, one row per event (a phase, a tool, a file or page written, a check, a repair, spend, the end), read by the website's owner, written only by the server, and the owner told on their own live topic when part 370 is there (once per batch written, with the newest event number). Events are added only through public.ai_site_job_add_events (server only), which numbers a batch after the newest under the job's row lock, so two writers never take the same number. Two indexes keep the background checks cheap: live jobs by lease, events by age (old events are pruned). store_theme_file_versions says who wrote each version (creator, ai, import, restore) and which job. No rows change. Safe to run again. */
ALTER TABLE IF EXISTS public.ai_site_jobs ADD COLUMN IF NOT EXISTS engine text NOT NULL DEFAULT 'classic' CHECK (engine IN ('classic', 'agent')), ADD COLUMN IF NOT EXISTS mode text CHECK (mode IS NULL OR mode IN ('blank', 'theme')), ADD COLUMN IF NOT EXISTS options jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS budget jsonb, ADD COLUMN IF NOT EXISTS phase text CHECK (phase IS NULL OR phase IN ('brief', 'plan', 'build', 'verify', 'repair', 'finish')), ADD COLUMN IF NOT EXISTS iteration integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS checkpoint jsonb CHECK (checkpoint IS NULL OR octet_length(checkpoint::text) <= 400000), ADD COLUMN IF NOT EXISTS cancel_requested_at timestamptz, ADD COLUMN IF NOT EXISTS last_event_seq integer NOT NULL DEFAULT 0;
ALTER TABLE IF EXISTS public.ai_site_jobs DROP CONSTRAINT IF EXISTS ai_site_jobs_status_check, ADD CONSTRAINT ai_site_jobs_status_check CHECK (status IN ('queued', 'running', 'complete', 'partial', 'failed', 'cancelled'));
ALTER TABLE IF EXISTS public.ai_site_jobs DROP CONSTRAINT IF EXISTS ai_site_jobs_step_check, ADD CONSTRAINT ai_site_jobs_step_check CHECK (step IN ('plan', 'build', 'write', 'photos', 'check', 'agent', 'done'));
DO $d$ BEGIN IF to_regclass('public.ai_site_jobs') IS NULL THEN RAISE NOTICE 'part 401: ai_site_jobs is not there yet. Run part 380, then this part again.'; RETURN; END IF; IF to_regclass('public.ai_site_jobs_one_live_per_install') IS NULL THEN IF EXISTS (SELECT 1 FROM public.ai_site_jobs WHERE status IN ('queued', 'running') GROUP BY install_id HAVING count(*) > 1) THEN RAISE NOTICE 'part 401: a website has two live AI jobs, so one live job per website is not enforced yet. Run this part again once they end.'; ELSE CREATE UNIQUE INDEX ai_site_jobs_one_live_per_install ON public.ai_site_jobs (install_id) WHERE status IN ('queued', 'running'); END IF; END IF; CREATE INDEX IF NOT EXISTS idx_ai_site_jobs_live ON public.ai_site_jobs (lease_until) WHERE status IN ('queued', 'running'); END $d$;
CREATE TABLE IF NOT EXISTS public.ai_site_job_events ( id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, job_id uuid NOT NULL REFERENCES public.ai_site_jobs(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, seq integer NOT NULL CHECK (seq > 0), kind text NOT NULL CHECK (kind IN ('phase', 'tool', 'file', 'page', 'tokens', 'validation', 'repair', 'note', 'spend', 'error', 'finished')), payload jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (octet_length(payload::text) <= 8192), created_at timestamptz NOT NULL DEFAULT now() );
CREATE UNIQUE INDEX IF NOT EXISTS ai_site_job_events_job_seq ON public.ai_site_job_events (job_id, seq);
CREATE INDEX IF NOT EXISTS idx_ai_site_job_events_created ON public.ai_site_job_events (created_at);
ALTER TABLE public.ai_site_job_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ai_site_job_events FROM anon, authenticated;
GRANT SELECT ON public.ai_site_job_events TO authenticated;
DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'ai_site_job_events' AND policyname = 'ai_site_job_events_select_own') THEN CREATE POLICY ai_site_job_events_select_own ON public.ai_site_job_events FOR SELECT TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid()))); END IF; END $p$;
CREATE OR REPLACE FUNCTION public.ai_site_job_event_tell() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ DECLARE r record; BEGIN IF to_regprocedure('public.storelib_tell_owner(uuid,text,jsonb)') IS NULL THEN RETURN NULL; END IF; FOR r IN SELECT n.job_id, max(n.seq) AS seq, j.owner_user_id FROM new_events n JOIN public.ai_site_jobs j ON j.id = n.job_id WHERE j.owner_user_id IS NOT NULL GROUP BY n.job_id, j.owner_user_id LOOP PERFORM public.storelib_tell_owner(r.owner_user_id, 'ai_job', jsonb_build_object('job_id', r.job_id, 'seq', r.seq)); END LOOP; RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.ai_site_job_event_tell() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS ai_site_job_events_tell ON public.ai_site_job_events;
CREATE TRIGGER ai_site_job_events_tell AFTER INSERT ON public.ai_site_job_events REFERENCING NEW TABLE AS new_events FOR EACH STATEMENT EXECUTE FUNCTION public.ai_site_job_event_tell();
CREATE OR REPLACE FUNCTION public.ai_site_job_add_events(p_job_id uuid, p_creator_id uuid, p_events jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ DECLARE v_seq integer; v_status text; v_top integer; BEGIN IF jsonb_typeof(p_events) IS DISTINCT FROM 'array' OR jsonb_array_length(p_events) = 0 THEN RETURN 0; END IF; SELECT j.last_event_seq, j.status INTO v_seq, v_status FROM public.ai_site_jobs j WHERE j.id = p_job_id AND j.creator_id = p_creator_id FOR UPDATE; IF NOT FOUND OR v_status NOT IN ('queued', 'running') THEN RETURN 0; END IF; SELECT max(x.seq) INTO v_top FROM public.ai_site_job_events x WHERE x.job_id = p_job_id; v_seq := greatest(coalesce(v_seq, 0), coalesce(v_top, 0)); INSERT INTO public.ai_site_job_events (job_id, creator_id, seq, kind, payload) SELECT p_job_id, p_creator_id, v_seq + t.n::integer, t.e->>'kind', coalesce(t.e->'payload', '{}'::jsonb) FROM jsonb_array_elements(p_events) WITH ORDINALITY AS t(e, n) WHERE t.n <= 50; v_seq := v_seq + least(jsonb_array_length(p_events), 50); UPDATE public.ai_site_jobs SET last_event_seq = v_seq WHERE id = p_job_id; RETURN v_seq; END $f$;
REVOKE ALL ON FUNCTION public.ai_site_job_add_events(uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ai_site_job_add_events(uuid, uuid, jsonb) TO service_role;
ALTER TABLE IF EXISTS public.store_theme_file_versions ADD COLUMN IF NOT EXISTS author text CHECK (author IS NULL OR author IN ('creator', 'ai', 'import', 'restore')), ADD COLUMN IF NOT EXISTS job_id uuid;
notify pgrst, 'reload schema';
